#[summary("clamp a value into a closed range")]
mod tasks {
    #[effects(pure)]
    #[uses(is_clamp, ordered)]
    fn clamp(x: i64, lo: i64, hi: i64) -> (r: i64)
        requires ordered(lo, hi),
        ensures is_clamp(x, lo, hi, r),
    {
        if x < lo {
            lo
        } else {
            if x > hi {
                hi
            } else {
                x
            }
        }
    }

    spec fn is_clamp(x: i64, lo: i64, hi: i64, r: i64) -> bool {
        if x < lo {
            r == lo
        } else {
            if x > hi {
                r == hi
            } else {
                r == x
            }
        }
    }

    spec fn ordered(lo: i64, hi: i64) -> bool {
        lo <= hi
    }
}

#[summary("floor midpoint of two i64")]
mod tasks {
    #[effects(pure)]
    #[uses(is_half)]
    fn half(x: i64) -> (h: i64)
        ensures is_half(x, h),
    {
        if x % 2 < 0 {
            (x - 1) / 2
        } else {
            x / 2
        }
    }

    spec fn is_half(x: i64, h: i64) -> bool {
        2 * h <= x && x < 2 * h + 2
    }

    spec fn is_mid(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }

    #[effects(pure)]
    #[uses(is_half, is_mid)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures is_mid(a, b, r),
    {
        let ha: i64 = half(a);
        let hb: i64 = half(b);
        let ra: i64 = a - 2 * ha;
        let rb: i64 = b - 2 * hb;
        let c: i64 = (ra + rb) / 2;
        ha + hb + c
    }
}

#[summary("saturating sum")]
mod tasks {
    spec fn inv(a: &[i64], i: usize, s: i64) -> bool {
        i <= a.len() && s == sat_prefix(a, i)
    }

    spec fn is_sat_sum(a: &[i64], r: i64) -> bool {
        r == sat_prefix(a, a.len())
    }

    spec fn is_step(x: i64, y: i64, r: i64) -> bool {
        r == step(x, y)
    }

    #[effects(pure)]
    #[uses(is_step, step)]
    fn sat_add(x: i64, y: i64) -> (r: i64)
        ensures is_step(x, y, r),
    {
        if y > 0 && x > 9223372036854775807 - y {
            9223372036854775807
        } else if y < 0 && x < -9223372036854775807 - 1 - y {
            -9223372036854775807 - 1
        } else {
            x + y
        }
    }

    spec fn sat_prefix(a: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else {
            step(sat_prefix(a, n - 1), a[n - 1])
        }
    }

    #[effects(pure)]
    #[uses(inv, is_sat_sum, is_step, sat_prefix)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures is_sat_sum(a, r),
    {
        let mut s: i64 = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant inv(a, i, s),
            decreases a.len() - i,
        {
            s = sat_add(s, a[i]);
            i = i + 1;
        }
        s
    }

    spec fn step(x: i64, y: i64) -> i64 {
        if x + y > 9223372036854775807 {
            9223372036854775807
        } else if x + y < -9223372036854775807 - 1 {
            -9223372036854775807 - 1
        } else {
            x + y
        }
    }
}

#[summary("count elements within an inclusive range")]
mod tasks {
    #[effects(pure)]
    #[uses(count_upto, inv, is_count)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures is_count(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut c: usize = 0;
        while i < a.len()
            invariant inv(a, lo, hi, i, c),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                c = c + 1;
            }
            i = i + 1;
        }
        c
    }

    spec fn count_upto(a: &[i64], n: usize, lo: i64, hi: i64) -> usize
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else if lo <= a[n - 1] && a[n - 1] <= hi {
            count_upto(a, n - 1, lo, hi) + 1
        } else {
            count_upto(a, n - 1, lo, hi)
        }
    }

    spec fn inv(a: &[i64], lo: i64, hi: i64, i: usize, c: usize) -> bool {
        i <= a.len() && c <= i && c == count_upto(a, i, lo, hi)
    }

    spec fn is_count(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        r == count_upto(a, a.len(), lo, hi)
    }
}

