        requires nonempty(a),
        ensures is_first_max(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant loop_inv(a, best, i),
            decreases a.len() - i,
        {
            if a[i] > a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn is_first_max(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|j: usize| j < a.len() ==> #[trigger] a[j] <= a[r]) && (forall|k: usize| k < r ==> #[trigger] a[k] < a[r])
    }

    spec fn loop_inv(a: &[i64], best: usize, i: usize) -> bool {
