#[summary("strictly increasing check")]
mod tasks {
    spec fn inv(a: &[i64], i: usize, ok: bool) -> bool {
        i <= a.len() && (ok ==> upto(a, i)) && (!ok ==> !upto(a, a.len()))
    }

    spec fn result_ok(a: &[i64], r: bool) -> bool {
        r == upto(a, a.len())
    }

    #[effects(pure)]
    #[uses(inv, result_ok, upto)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures result_ok(a, r),
    {
        let mut i: usize = 0;
        let mut ok: bool = true;
        while ok && i + 1 < a.len()
            invariant inv(a, i, ok),
            decreases a.len() - i,
        {
            if a[i] >= a[i + 1] {
                ok = false;
            }
            i = i + 1;
        }
        ok
    }

    spec fn upto(a: &[i64], n: usize) -> bool {
        forall|j: usize| j < n && j + 1 < a.len() ==> #[trigger] a[j] < a[j + 1]
    }
}

#[summary("binary search lower bound")]
mod tasks {
    spec fn above(a: &[i64], t: i64, hi: usize) -> bool {
        forall|i: usize| hi <= i && i < a.len() ==> #[trigger] a[i] >= t
    }

    spec fn below(a: &[i64], t: i64, lo: usize) -> bool {
        forall|i: usize| i < lo && i < a.len() ==> #[trigger] a[i] < t
    }

    spec fn bounds(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    #[effects(pure)]
    #[uses(above, below, bounds, sorted)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires sorted(a),
        ensures bounds(a, r, r), below(a, t, r), above(a, t, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant bounds(a, lo, hi), below(a, t, lo), above(a, t, hi), sorted(a),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] < t {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }
}

