    }

    spec fn dst_part(a: &[i64], o: &[i64], k: usize, i: usize) -> bool {
        a.len() == o.len() && (forall|j: usize| j < i && j < a.len() ==> #[trigger] dst_one(a, o, k, j))
    }

    spec fn l1_post(n: usize, i: usize, k: usize) -> bool {
        (i + k) % n == (i + k % n) % n
    }

    spec fn l1_pre(n: usize, i: usize, k: usize) -> bool {
        n > 0 && i < n
    }

    spec fn l2_post(n: usize, i: usize, m: usize) -> bool {
        (i + m) % n == (if i + m < n { i + m } else { i + m - n })
    }

    spec fn l2_pre(n: usize, i: usize, m: usize) -> bool {
        n > 0 && i < n && m < n
    }

    #[effects(pure)]
    #[uses(l1_post, l1_pre)]
    fn lemma1(n: usize, i: usize, k: usize) -> ()
        requires l1_pre(n, i, k),
        ensures l1_post(n, i, k),
    {}

    #[effects(pure)]
    #[uses(l2_post, l2_pre)]
    fn lemma2(n: usize, i: usize, m: usize) -> ()
        requires l2_pre(n, i, m),
        ensures l2_post(n, i, m),
    {}

    spec fn mod_eq(n: usize, i: usize, k: usize, p: usize) -> bool {
        (i + k) % n == p
    }

    #[effects(pure)]
    #[uses(l1_post, l1_pre, l2_post, l2_pre, mod_eq, pos3)]
    fn mod_fact(n: usize, i: usize, k: usize, m: usize) -> ()
        requires pos3(n, i, k, m),
        ensures mod_eq(n, i, k, if i + m < n { i + m } else { i + m - n }),
    {
        lemma1(n, i, k);
        lemma2(n, i, m);
    }

    spec fn pos3(n: usize, i: usize, k: usize, m: usize) -> bool {
        n > 0 && i < n && m < n && m == k % n
    }

    spec fn rev_inv(a: &[i64], o: &[i64], lo: usize, hi: usize, i: usize, j: usize) -> bool {
        a.len() == o.len() && (forall|k: usize| k < a.len() ==> #[trigger] a[k] == (if lo <= k && k < i || j <= k && k < hi { o[lo + hi - 1 - k] } else { o[k] }))
    }

    spec fn rev_post(a: &[i64], o: &[i64], lo: usize, hi: usize) -> bool {
        a.len() == o.len() && (forall|i: usize| i < a.len() ==> #[trigger] a[i] == (if lo <= i && i < hi { o[lo + hi - 1 - i] } else { o[i] }))
    }

    #[effects(pure)]
    #[uses(bounds, rev_inv, rev_post)]
    fn reverse_range(a: &mut [i64], lo: usize, hi: usize) -> ()
        requires bounds(a, lo, hi),
        ensures rev_post(a, old(a), lo, hi),
    {
        let mut i: usize = lo;
        let mut j: usize = hi;
        while i < j
            invariant bounds(a, lo, hi), lo <= i, j <= hi, i + j == lo + hi, i <= j + 1, rev_inv(a, old(a), lo, hi, i, j),
            decreases j - i,
        {
